CREATE TABLE `analysis` (
  `analysis_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mgi_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `parameter_id` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `parameter_name_unlinked` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mouse_strain` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `mouse_life_stage` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pvalue` double DEFAULT NULL,
  `allele_symbol` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `source_file` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`analysis_id`),
  KEY `idx_analysis_mgi` (`mgi_id`),
  KEY `idx_analysis_parameter` (`parameter_id`),
  KEY `idx_analysis_pvalue` (`pvalue`),
  CONSTRAINT `fk_analysis_gene` FOREIGN KEY (`mgi_id`) REFERENCES `gene` (`mgi_id`),
  CONSTRAINT `fk_analysis_parameter` FOREIGN KEY (`parameter_id`) REFERENCES `parameter` (`parameter_id`),
  CONSTRAINT `chk_analysis_id` CHECK (regexp_like(`analysis_id`,_utf8mb4'^an[0-9]{10}$')),
  CONSTRAINT `chk_analysis_pvalue` CHECK ((`pvalue` between 0 and 1)),
  CONSTRAINT `chk_analysis_stage` CHECK ((`mouse_life_stage` in (_utf8mb4'E9.5',_utf8mb4'E12.5',_utf8mb4'E15.5',_utf8mb4'E18.5',_utf8mb4'Early adult',_utf8mb4'Middle aged adult',_utf8mb4'Late adult'))),
  CONSTRAINT `chk_analysis_strain` CHECK ((`mouse_strain` in (_utf8mb4'B6Brd;B6Dnk;B6N-Tyr<c-Brd>',_utf8mb4'C57BL/6Brd-Tyr<c-Brd>',_utf8mb4'C57BL/6Dnk',_utf8mb4'C57BL/6JTyr;C57BL/6N',_utf8mb4'C57BL/6N',_utf8mb4'C57BL/6NCrl',_utf8mb4'C57BL/6NJ',_utf8mb4'C57BL/6NTac',_utf8mb4'C57BL/6NTacDen')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='One row per IMPC analysis (knockout gene x parameter)';
