DROP TABLE IF EXISTS `disease`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `disease` (
  `doid` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `disease_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`doid`),
  CONSTRAINT `chk_doid` CHECK (regexp_like(`doid`,_utf8mb4'^DOID:[0-9]+$'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Disease Ontology terms';
/*!40101 SET character_set_client = @saved_cs_client */;

