--
-- Table structure for table `ensembl_gene`
--

DROP TABLE IF EXISTS `ensembl_gene`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `ensembl_gene` (
  `ensembl_gene_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `species_id` int NOT NULL,
  `gene_name` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mgi_id` varchar(15) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`ensembl_gene_id`),
  KEY `idx_ensembl_mgi` (`mgi_id`),
  KEY `idx_ensembl_name` (`gene_name`),
  KEY `fk_ensembl_species` (`species_id`),
  CONSTRAINT `fk_ensembl_mgi` FOREIGN KEY (`mgi_id`) REFERENCES `gene` (`mgi_id`),
  CONSTRAINT `fk_ensembl_species` FOREIGN KEY (`species_id`) REFERENCES `species` (`species_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Ensembl genes of all species (bespoke homology task)';
/*!40101 SET character_set_client = @saved_cs_client */;

