DROP TABLE IF EXISTS `gene_disease`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gene_disease` (
  `gene_disease_id` int NOT NULL,
  `mgi_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `doid` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`gene_disease_id`),
  UNIQUE KEY `uq_gene_disease` (`mgi_id`,`doid`),
  KEY `idx_gd_doid` (`doid`),
  CONSTRAINT `fk_gd_disease` FOREIGN KEY (`doid`) REFERENCES `disease` (`doid`),
  CONSTRAINT `fk_gd_gene` FOREIGN KEY (`mgi_id`) REFERENCES `gene` (`mgi_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Gene-disease associations';
