--
-- Table structure for table `homology`
--

DROP TABLE IF EXISTS `homology`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `homology` (
  `mouse_ensembl_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `homolog_ensembl_id` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `homology_type` enum('ortholog_one2one','ortholog_one2many','ortholog_many2many') COLLATE utf8mb4_unicode_ci NOT NULL,
  `percent_identity` double NOT NULL,
  `last_common_ancestor` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`mouse_ensembl_id`,`homolog_ensembl_id`),
  KEY `idx_homolog` (`homolog_ensembl_id`),
  CONSTRAINT `fk_hom_homolog` FOREIGN KEY (`homolog_ensembl_id`) REFERENCES `ensembl_gene` (`ensembl_gene_id`),
  CONSTRAINT `fk_hom_mouse` FOREIGN KEY (`mouse_ensembl_id`) REFERENCES `ensembl_gene` (`ensembl_gene_id`),
  CONSTRAINT `chk_hom_identity` CHECK ((`percent_identity` between 0 and 100))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Mouse gene -> homolog in another species';
/*!40101 SET character_set_client = @saved_cs_client */;

