--
-- Table structure for table `human_gene`
--

DROP TABLE IF EXISTS `human_gene`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `human_gene` (
  `hgnc_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `human_symbol` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL,
  `human_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mgi_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`hgnc_id`),
  UNIQUE KEY `uq_human_gene_mgi` (`mgi_id`),
  CONSTRAINT `fk_human_gene_mouse` FOREIGN KEY (`mgi_id`) REFERENCES `gene` (`mgi_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Human genes with a one-to-one mouse ortholog';
/*!40101 SET character_set_client = @saved_cs_client */;

