DROP TABLE IF EXISTS `impc_procedure`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `impc_procedure` (
  `procedure_id` int NOT NULL,
  `procedure_name` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `is_mandatory` tinyint(1) NOT NULL,
  PRIMARY KEY (`procedure_id`),
  UNIQUE KEY `uq_procedure_name` (`procedure_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='The 51 IMPC phenotyping procedures';
/*!40101 SET character_set_client = @saved_cs_client */;

