/*!40000 ALTER TABLE `impc_procedure` DISABLE KEYS */;
INSERT INTO `impc_procedure` VALUES (1,'Acoustic Startle and Pre-pulse Inhibition (PPI)',NULL,1),(2,'Adult LacZ',NULL,0),(3,'Auditory Brain Stem Response','Auditory brainstem response test determines hearing sensitivity and other physiological parameters using evoked potential recordings in anesthetized mice.Ontological description: MP:0004738 - abnormal brainstem auditory evoked potential.',1),(4,'Body Composition (DEXA lean/fat)','Measure bone mineral content and density as well as body composition in mice using the DEXA (Dual Energy X-ray Absorptiometry) analyser.',1),(5,'Body Weight',NULL,1),(6,'Challenge Whole Body Plethysmography',NULL,0),(7,'Clinical Chemistry',NULL,1),(8,'Combined SHIRPA and Dysmorphology','SHIRPA and dysmorphology were originally always separate assessments.&nbsp; However they have recently been combined as assessments so that they take place at the same time.The purpose of the assessments is to examine mice for obvious physical characteristics behaviors and morphological abnormalities.Descriptions include abnormal locomotion/appearance/behavior/reflex reactions.',1),(9,'Echo','To assess the functionality of the heart in order to determine the presence of a mutant phenotype.',0),(10,'Electrocardiogram (ECG)','To provide a high throughput method to obtain Electrocardiograms in a conscious mouse or an anesthetized mouse.',1),(11,'Embryo LacZ',NULL,0),(12,'Experimental design',NULL,0),(13,'Eye Morphology','To detect abnormalities in eye morphology.',1),(14,'Fear Conditioning','Fear Conditioning test assesses aversive learning and memory',0),(15,'Fertility of Homozygous Knock-out Mice','To assess the fertility of homozygous knockout mice.',1),(16,'Formalin Test',NULL,0),(17,'Grip Strength',NULL,1),(18,'Gross Morphology Embryo E12.5',NULL,0),(19,'Gross Morphology Embryo E14.5-E15.5',NULL,0),(20,'Gross Morphology Embryo E18.5',NULL,0),(21,'Gross Morphology Embryo E9.5',NULL,0),(22,'Gross Morphology Placenta E12.5',NULL,0),(23,'Gross Morphology Placenta E14.5-E15.5',NULL,0),(24,'Gross Morphology Placenta E18.5',NULL,0),(25,'Gross Morphology Placenta E9.5',NULL,0),(26,'Gross Pathology and Tissue Collection',NULL,1),(27,'Heart Weight','To evaluate cardiac size using heart weight and body weight.',1),(28,'Hematology','Hematological assessment of blood determines blood cell counts (white blood cells red blood cells hemoglobin and platelets) and additional hematological parameters (hematocrit mean cell volume mean corpuscular hemoglobin mean cell hemoglobin concentration) can be derived using these indices. These tests will indicate abnormalities in the production of blood and its components (blood cells and hemoglobin) as well as in the associated blood-forming organs.&nbsp;Ontological description: MP:0002429 - abnormal blood cell morphology/development.',1),(29,'Histopathology',NULL,0),(30,'Housing and Husbandry','Housing_and_husbandry',0),(31,'Immunophenotyping','Immunophenotyping of immune system cells',1),(32,'Indirect Calorimetry',NULL,0),(33,'Insulin Blood Level','The insulin concentration in the blood is an important indicator of diabetes.Ontological description: abnormal circulating insulin level [MP:0001560]; increased circulating insulin level [MP:0002079]; decreased circulating insulin level [MP:0002727].',0),(34,'Intraperitoneal glucose tolerance test (IPGTT)',NULL,1),(35,'Light-Dark Test','Light-Dark test monitors the anxiety-related behaviour of mice',0),(36,'MicroCT E14.5-E15.5',NULL,0),(37,'MicroCT E14.5-E15.5 Analysis',NULL,0),(38,'MicroCT E18.5',NULL,0),(39,'MicroCT E9.5',NULL,0),(40,'Open Field','The Open Field test is used to assess anxiety and exploratory behaviors. It is based on the natural tendency of an animal to explore and to protect itself using avoidance which translates to a normal animal spending more time in the periphery of the Open Field arena than in the center (the most anxiogenic area).',1),(41,'OPT E9.5',NULL,0),(42,'Organ Weight','Organ weights from different tissues collected for IMPC',0),(43,'Tissue Embedding and Block Banking','Collect and fix a standard list of tissues from the complete necropsy (see IMPC Gross Pathology &amp; Tissue Collection SOP)Trim the fixed tissues into cassettes for processingEmbed the tissues in paraffin in a standard orientation',0),(44,'Viability E12.5 Secondary Screen',NULL,0),(45,'Viability E14.5-E15.5 Secondary Screen',NULL,0),(46,'Viability E18.5 Secondary Screen',NULL,0),(47,'Viability E9.5 Secondary Screen',NULL,0),(48,'Viability Primary Screen','Assess the viability of mutant mice of each sex and zygosity.',1),(49,'Welfare Observations','The Welfare Observations procedure is used for the recording of welfare issues as and when they occur.',0),(50,'X-ray','Construct and analyse digital X-ray images in immobilised mice using a Faxitron X-Ray system or NTB digital X-ray scanner.',1),(51,'Y-maze','Y-maze assesses learning and memory; it can be used instead/in parallel of Fear Conditioning',0);
/*!40000 ALTER TABLE `impc_procedure` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `lacz_expression`
--

DROP TABLE IF EXISTS `lacz_expression`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lacz_expression` (
  `analysis_id` varchar(15) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tissue` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `expression` varchar(25) COLLATE utf8mb4_unicode_ci NOT NULL,
  PRIMARY KEY (`analysis_id`,`tissue`),
  KEY `idx_lacz_tissue_expr` (`tissue`,`expression`),
  CONSTRAINT `fk_lacz_analysis` FOREIGN KEY (`analysis_id`) REFERENCES `analysis` (`analysis_id`),
  CONSTRAINT `chk_lacz_expression` CHECK ((`expression` in (_utf8mb4'expression',_utf8mb4'no expression',_utf8mb4'ambiguous',_utf8mb4'imageOnly',_utf8mb4'No data',_utf8mb4'tissue not available'))),
  CONSTRAINT `chk_lacz_tissue` CHECK ((`tissue` in (_utf8mb4'blood',_utf8mb4'brain',_utf8mb4'colon',_utf8mb4'eye',_utf8mb4'heart',_utf8mb4'kidney',_utf8mb4'liver',_utf8mb4'lung',_utf8mb4'skeletal_muscle',_utf8mb4'skin',_utf8mb4'vascular_system')))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='LacZ reporter expression: one row per analysis per tissue';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `lacz_expression`
--

LOCK TABLES `lacz_expression` WRITE;
/*!40000 ALTER TABLE `lacz_expression` DISABLE KEYS */;
